/bin/bash -lc "node --disable-warning=ExperimentalWarning --input-type=module <<'NODE'
import { DatabaseSync } from 'node:sqlite';
import { spawn } from 'node:child_process';
import { setTimeout as sleep } from 'node:timers/promises';
const path = '/tmp/job-tracker-interrupted-third.db';
const db = new DatabaseSync(path);
db.exec(\"DROP TABLE IF EXISTS jobs; DROP TABLE IF EXISTS idempotency; DROP TABLE IF EXISTS worker_heartbeat;\");
db.exec(\"CREATE TABLE jobs(id TEXT PRIMARY KEY,status TEXT NOT NULL,input TEXT NOT NULL,steps INTEGER NOT NULL,fail_attempts INTEGER NOT NULL,attempts INTEGER NOT NULL,progress_completed INTEGER NOT NULL,result_output TEXT,error TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,available_at INTEGER NOT NULL DEFAULT 0); CREATE TABLE idempotency(key TEXT PRIMARY KEY,payload TEXT NOT NULL,job_id TEXT NOT NULL); CREATE TABLE worker_heartbeat(id INTEGER PRIMARY KEY,seen_at INTEGER NOT NULL);\");
const now = new Date().toISOString();
db.prepare(\"INSERT INTO jobs VALUES('restart-case','running','recover me',20,2,3,5,NULL,NULL,?,?,0)\").run(now,now);
const child = spawn('node',['--disable-warning=ExperimentalWarning','dist/worker.js'],{env:{...process.env,DATABASE_PATH:path},stdio:'ignore'});
let done;
for (let i=0;i<50;i++) { await sleep(100); const row=db.prepare(\"SELECT status,attempts,progress_completed,result_output,error FROM jobs WHERE id='restart-case'\").get(); if(row.status==='completed'||row.status==='failed'){done=row;break;} }
child.kill('SIGTERM'); await new Promise(resolve=>child.once('exit',resolve)); console.log(JSON.stringify(done ?? db.prepare(\"SELECT status,attempts,progress_completed,result_output,error FROM jobs WHERE id='restart-case'\").get()));
db.close();
NODE"

